bool fits(const vector<int>& w, int k, int cap) {
    int groups = 1, sum = 0;
    for (int x : w) {
        if (sum + x > cap) {
            groups++;
            sum = 0;
        }
        sum += x;
    }
    return groups <= k;
}

int minCapacity(const vector<int>& w, int k) {
    int lo = *max_element(w.begin(), w.end());
    int hi = accumulate(w.begin(), w.end(), 0) + 1;  // search space [lo, hi)
    while (lo < hi) {
        int mid = lo + (hi - lo) / 2;
        if (fits(w, k, mid)) hi = mid;
        else lo = mid + 1;
    }
    // lo = smallest cap that fits
    return lo;
}

int intSqrt(int x) {
    long long lo = 0, hi = x + 1LL;  // search space [lo, hi)
    while (lo < hi) {
        long long mid = lo + (hi - lo) / 2;
        if (mid * mid > x) hi = mid;
        else lo = mid + 1;
    }
    // lo = first value whose square exceeds x
    return lo - 1;
}

int findMinIndex(const vector<int>& a) {
    int n = a.size();
    int lo = 0, hi = n;              // search space [lo, hi)
    while (lo < hi) {
        int mid = lo + (hi - lo) / 2;
        if (a[mid] <= a[n - 1]) hi = mid;
        else lo = mid + 1;
    }
    // lo = first index with a[i] <= a[n - 1]
    return lo;
}

int searchRotated(const vector<int>& a, int target) {
    int n = a.size();
    auto pred = [&](int i) {
        bool left = a[i] > a[n - 1], targetLeft = target > a[n - 1];
        return left == targetLeft ? a[i] >= target : targetLeft;
    };
    int lo = 0, hi = n;              // search space [lo, hi)
    while (lo < hi) {
        int mid = lo + (hi - lo) / 2;
        if (pred(mid)) hi = mid;
        else lo = mid + 1;
    }
    // lo = first index where pred is true, or n if none
    return lo < n && a[lo] == target ? lo : -1;
}

pair<int, int> twoSumSorted(const vector<int>& a, int target) {
    int n = a.size();
    int l = 0, r = n - 1;
    while (l < r) {
        int sum = a[l] + a[r];
        if (sum == target) return {l, r};
        if (sum < target) l++;
        else r--;
    }
    return {-1, -1};
}

int removeDuplicates(vector<int>& a) {
    int k = 0;
    for (int x : a) {
        if (k == 0 || x != a[k - 1]) a[k++] = x;
    }
    return k;
}

vector<vector<int>> threeSum(vector<int> a) {
    sort(a.begin(), a.end());
    int n = a.size();
    vector<vector<int>> ans;
    for (int i = 0; i < n; i++) {
        if (i > 0 && a[i] == a[i - 1]) continue;
        int l = i + 1, r = n - 1;
        while (l < r) {
            int sum = a[i] + a[l] + a[r];
            if (sum < 0) l++;
            else if (sum > 0) r--;
            else {
                ans.push_back({a[i], a[l], a[r]});
                l++;
                while (l < r && a[l] == a[l - 1]) l++;
            }
        }
    }
    return ans;
}

int maxWindowSum(const vector<int>& a, int k) {
    int n = a.size(), sum = 0, ans = INT_MIN;
    for (int r = 0; r < n; r++) {
        sum += a[r];
        if (r >= k) sum -= a[r - k];
        if (r >= k - 1) ans = max(ans, sum);
    }
    return ans;
}

int longestUnique(const string& s) {
    unordered_map<char, int> cnt;
    int n = s.size(), l = 0, ans = 0;
    for (int r = 0; r < n; r++) {
        cnt[s[r]]++;
        while (cnt[s[r]] > 1) {
            cnt[s[l]]--;
            l++;
        }
        ans = max(ans, r - l + 1);
    }
    return ans;
}

int minLenAtLeast(const vector<int>& a, int target) {
    int n = a.size(), l = 0, sum = 0, ans = INT_MAX;
    for (int r = 0; r < n; r++) {
        sum += a[r];
        while (sum >= target) {
            ans = min(ans, r - l + 1);
            sum -= a[l];
            l++;
        }
    }
    return ans == INT_MAX ? 0 : ans;
}

long long countAtMost(const vector<int>& a, int k) {
    unordered_map<int, int> cnt;
    int n = a.size(), l = 0;
    long long ans = 0;
    for (int r = 0; r < n; r++) {
        cnt[a[r]]++;
        while ((int)cnt.size() > k) {
            if (--cnt[a[l]] == 0) cnt.erase(a[l]);
            l++;
        }
        ans += r - l + 1;
    }
    return ans;
}

int countSumK(const vector<int>& a, int k) {
    unordered_map<int, int> cnt;
    cnt[0] = 1;
    int sum = 0, ans = 0;
    for (int x : a) {
        sum += x;
        if (cnt.count(sum - k)) ans += cnt[sum - k];
        cnt[sum]++;
    }
    return ans;
}

vector<int> rangeAdd(int n, const vector<array<int, 3>>& ops) {
    vector<int> diff(n + 1, 0);
    for (auto [l, r, x] : ops) {
        diff[l] += x;
        diff[r + 1] -= x;
    }
    vector<int> ans(n);
    int sum = 0;
    for (int i = 0; i < n; i++) {
        sum += diff[i];
        ans[i] = sum;
    }
    return ans;
}

vector<int> nextGreater(const vector<int>& a) {
    int n = a.size();
    vector<int> ans(n, -1);
    stack<int> st;
    for (int i = 0; i < n; i++) {
        while (!st.empty() && a[st.top()] < a[i]) {
            ans[st.top()] = i;
            st.pop();
        }
        st.push(i);
    }
    return ans;
}

int largestRectangle(vector<int> h) {
    h.push_back(0);
    int n = h.size(), ans = 0;
    stack<int> st;
    for (int i = 0; i < n; i++) {
        while (!st.empty() && h[st.top()] >= h[i]) {
            int height = h[st.top()];
            st.pop();
            int l = st.empty() ? -1 : st.top();
            ans = max(ans, height * (i - l - 1));
        }
        st.push(i);
    }
    return ans;
}

vector<int> windowMax(const vector<int>& a, int k) {
    int n = a.size();
    deque<int> dq;
    vector<int> ans;
    for (int i = 0; i < n; i++) {
        while (!dq.empty() && a[dq.back()] <= a[i]) dq.pop_back();
        dq.push_back(i);
        if (dq.front() <= i - k) dq.pop_front();
        if (i >= k - 1) ans.push_back(a[dq.front()]);
    }
    return ans;
}

ListNode* reverseList(ListNode* head) {
    ListNode* prev = nullptr;
    ListNode* cur = head;
    while (cur) {
        ListNode* nxt = cur->next;
        cur->next = prev;
        prev = cur;
        cur = nxt;
    }
    return prev;
}

ListNode* middleNode(ListNode* head) {
    ListNode* slow = head;
    ListNode* fast = head;
    while (fast && fast->next) {
        slow = slow->next;
        fast = fast->next->next;
    }
    return slow;
}

ListNode* mergeLists(ListNode* a, ListNode* b) {
    ListNode dummy(0);
    ListNode* tail = &dummy;
    while (a && b) {
        if (a->val <= b->val) {
            tail->next = a;
            a = a->next;
        } else {
            tail->next = b;
            b = b->next;
        }
        tail = tail->next;
    }
    tail->next = a ? a : b;
    return dummy.next;
}

bool hasCycle(ListNode* head) {
    ListNode* slow = head;
    ListNode* fast = head;
    while (fast && fast->next) {
        slow = slow->next;
        fast = fast->next->next;
        if (slow == fast) return true;
    }
    return false;
}

ListNode* removeNthFromEnd(ListNode* head, int k) {
    ListNode dummy(0);
    dummy.next = head;
    ListNode* fast = &dummy;
    ListNode* slow = &dummy;
    for (int i = 0; i < k; i++) fast = fast->next;
    while (fast->next) {
        fast = fast->next;
        slow = slow->next;
    }
    slow->next = slow->next->next;
    return dummy.next;
}

void preorder(TreeNode* node, vector<int>& out) {
    if (!node) return;
    out.push_back(node->val);
    preorder(node->left, out);
    preorder(node->right, out);
}

void inorder(TreeNode* node, vector<int>& out) {
    if (!node) return;
    inorder(node->left, out);
    out.push_back(node->val);
    inorder(node->right, out);
}

void postorder(TreeNode* node, vector<int>& out) {
    if (!node) return;
    postorder(node->left, out);
    postorder(node->right, out);
    out.push_back(node->val);
}

vector<int> inorderIter(TreeNode* root) {
    vector<int> ans;
    stack<TreeNode*> st;
    TreeNode* cur = root;
    while (cur || !st.empty()) {
        while (cur) {
            st.push(cur);
            cur = cur->left;
        }
        cur = st.top();
        st.pop();
        ans.push_back(cur->val);
        cur = cur->right;
    }
    return ans;
}

int height(TreeNode* node, int& best) {
    if (!node) return 0;
    int l = height(node->left, best);
    int r = height(node->right, best);
    best = max(best, l + r);
    return 1 + max(l, r);
}

int diameter(TreeNode* root) {
    int best = 0;
    height(root, best);
    return best;
}

vector<vector<int>> levelOrder(TreeNode* root) {
    vector<vector<int>> ans;
    if (!root) return ans;
    queue<TreeNode*> q;
    q.push(root);
    while (!q.empty()) {
        int sz = q.size();
        vector<int> level;
        for (int i = 0; i < sz; i++) {
            TreeNode* node = q.front();
            q.pop();
            level.push_back(node->val);
            if (node->left) q.push(node->left);
            if (node->right) q.push(node->right);
        }
        ans.push_back(level);
    }
    return ans;
}

bool validate(TreeNode* node, long long lo, long long hi) {
    if (!node) return true;
    if (node->val <= lo || node->val >= hi) return false;
    return validate(node->left, lo, node->val) && validate(node->right, node->val, hi);
}

bool isValidBST(TreeNode* root) {
    return validate(root, LLONG_MIN, LLONG_MAX);
}

TreeNode* insertBST(TreeNode* root, int x) {
    if (!root) return new TreeNode(x);
    if (x < root->val) root->left = insertBST(root->left, x);
    else root->right = insertBST(root->right, x);
    return root;
}

struct TrieNode {
    TrieNode* next[26] = {};
    bool isEnd = false;
};

void insert(TrieNode* root, const string& word) {
    TrieNode* cur = root;
    for (char c : word) {
        int i = c - 'a';
        if (!cur->next[i]) cur->next[i] = new TrieNode();
        cur = cur->next[i];
    }
    cur->isEnd = true;
}

bool search(TrieNode* root, const string& word) {
    TrieNode* cur = root;
    for (char c : word) {
        int i = c - 'a';
        if (!cur->next[i]) return false;
        cur = cur->next[i];
    }
    return cur->isEnd;
}

vector<int> topK(const vector<int>& a, int k) {
    priority_queue<int, vector<int>, greater<int>> pq;
    for (int x : a) {
        pq.push(x);
        if ((int)pq.size() > k) pq.pop();
    }
    vector<int> ans;
    while (!pq.empty()) {
        ans.push_back(pq.top());
        pq.pop();
    }
    return ans;
}

struct MedianFinder {
    priority_queue<int> lo;
    priority_queue<int, vector<int>, greater<int>> hi;
    void add(int x) {
        lo.push(x);
        hi.push(lo.top());
        lo.pop();
        if (hi.size() > lo.size()) {
            lo.push(hi.top());
            hi.pop();
        }
    }
    double median() {
        if (lo.size() > hi.size()) return lo.top();
        return (1LL * lo.top() + hi.top()) / 2.0;
    }
};

vector<int> mergeK(const vector<vector<int>>& lists) {
    using T = tuple<int, int, int>;
    priority_queue<T, vector<T>, greater<T>> pq;
    int k = lists.size();
    for (int i = 0; i < k; i++) {
        if (!lists[i].empty()) pq.push({lists[i][0], i, 0});
    }
    vector<int> ans;
    while (!pq.empty()) {
        auto [x, i, j] = pq.top();
        pq.pop();
        ans.push_back(x);
        if (j + 1 < (int)lists[i].size()) pq.push({lists[i][j + 1], i, j + 1});
    }
    return ans;
}

void dfs(vector<string>& grid, int r, int c) {
    int m = grid.size(), n = grid[0].size();
    if (r < 0 || r >= m || c < 0 || c >= n || grid[r][c] != '1') return;
    grid[r][c] = '0';
    dfs(grid, r + 1, c);
    dfs(grid, r - 1, c);
    dfs(grid, r, c + 1);
    dfs(grid, r, c - 1);
}

int countIslands(vector<string>& grid) {
    int m = grid.size(), n = grid[0].size(), ans = 0;
    for (int r = 0; r < m; r++) {
        for (int c = 0; c < n; c++) {
            if (grid[r][c] == '1') {
                dfs(grid, r, c);
                ans++;
            }
        }
    }
    return ans;
}

int shortestPath(const vector<string>& grid, int sr, int sc, int tr, int tc) {
    const int dirs[4][2] = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
    int m = grid.size(), n = grid[0].size();
    vector<vector<int>> dist(m, vector<int>(n, -1));
    queue<pair<int, int>> q;
    dist[sr][sc] = 0;
    q.push({sr, sc});
    while (!q.empty()) {
        auto [r, c] = q.front();
        q.pop();
        if (r == tr && c == tc) return dist[r][c];
        for (auto& d : dirs) {
            int nr = r + d[0], nc = c + d[1];
            if (nr < 0 || nr >= m || nc < 0 || nc >= n) continue;
            if (grid[nr][nc] == '#' || dist[nr][nc] != -1) continue;
            dist[nr][nc] = dist[r][c] + 1;
            q.push({nr, nc});
        }
    }
    return -1;
}

vector<vector<int>> nearestSource(const vector<vector<int>>& grid) {
    const int dirs[4][2] = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
    int m = grid.size(), n = grid[0].size();
    vector<vector<int>> dist(m, vector<int>(n, -1));
    queue<pair<int, int>> q;
    for (int r = 0; r < m; r++) {
        for (int c = 0; c < n; c++) {
            if (grid[r][c] == 1) {
                dist[r][c] = 0;
                q.push({r, c});
            }
        }
    }
    while (!q.empty()) {
        auto [r, c] = q.front();
        q.pop();
        for (auto& d : dirs) {
            int nr = r + d[0], nc = c + d[1];
            if (nr < 0 || nr >= m || nc < 0 || nc >= n || dist[nr][nc] != -1) continue;
            dist[nr][nc] = dist[r][c] + 1;
            q.push({nr, nc});
        }
    }
    return dist;
}

vector<vector<int>> buildGraph(int n, const vector<pair<int, int>>& edges) {
    vector<vector<int>> adj(n);
    for (auto [u, v] : edges) {
        adj[u].push_back(v);
        adj[v].push_back(u);
    }
    return adj;
}

vector<int> topoSort(int n, const vector<vector<int>>& adj) {
    vector<int> indeg(n, 0);
    for (int u = 0; u < n; u++) {
        for (int v : adj[u]) indeg[v]++;
    }
    queue<int> q;
    for (int u = 0; u < n; u++) {
        if (indeg[u] == 0) q.push(u);
    }
    vector<int> order;
    while (!q.empty()) {
        int u = q.front();
        q.pop();
        order.push_back(u);
        for (int v : adj[u]) {
            if (--indeg[v] == 0) q.push(v);
        }
    }
    if ((int)order.size() < n) return {};
    return order;
}

bool dfs(int u, const vector<vector<int>>& adj, vector<int>& color) {
    color[u] = 1;
    for (int v : adj[u]) {
        if (color[v] == 1) return true;
        if (color[v] == 0 && dfs(v, adj, color)) return true;
    }
    color[u] = 2;
    return false;
}

bool hasCycle(int n, const vector<vector<int>>& adj) {
    vector<int> color(n, 0);
    for (int u = 0; u < n; u++) {
        if (color[u] == 0 && dfs(u, adj, color)) return true;
    }
    return false;
}

struct DSU {
    vector<int> parent, sz;
    DSU(int n) : parent(n), sz(n, 1) {
        iota(parent.begin(), parent.end(), 0);
    }
    int find(int x) {
        if (parent[x] != x) parent[x] = find(parent[x]);
        return parent[x];
    }
    bool unite(int a, int b) {
        a = find(a);
        b = find(b);
        if (a == b) return false;
        if (sz[a] < sz[b]) swap(a, b);
        parent[b] = a;
        sz[a] += sz[b];
        return true;
    }
};

vector<int> dijkstra(int n, const vector<vector<pair<int, int>>>& adj, int src) {
    using P = pair<int, int>;
    vector<int> dist(n, INT_MAX);
    priority_queue<P, vector<P>, greater<P>> pq;
    dist[src] = 0;
    pq.push({0, src});
    while (!pq.empty()) {
        auto [d, u] = pq.top();
        pq.pop();
        if (d > dist[u]) continue;
        for (auto [v, w] : adj[u]) {
            if (d + w < dist[v]) {
                dist[v] = d + w;
                pq.push({dist[v], v});
            }
        }
    }
    return dist;
}

int bellmanFord(int n, const vector<array<int, 3>>& edges, int src, int dst, int k) {
    vector<int> dist(n, INT_MAX);
    dist[src] = 0;
    for (int i = 0; i < k; i++) {
        vector<int> prev = dist;
        for (auto [u, v, w] : edges) {
            if (prev[u] != INT_MAX) dist[v] = min(dist[v], prev[u] + w);
        }
    }
    return dist[dst];
}

int kruskal(int n, vector<array<int, 3>> edges) {
    sort(edges.begin(), edges.end());
    DSU dsu(n);
    int total = 0, used = 0;
    for (auto [w, u, v] : edges) {
        if (dsu.unite(u, v)) {
            total += w;
            used++;
        }
    }
    return used == n - 1 ? total : -1;
}

void dfs(const vector<int>& a, int start, vector<int>& cur, vector<vector<int>>& ans) {
    ans.push_back(cur);
    for (int i = start; i < (int)a.size(); i++) {
        cur.push_back(a[i]);
        dfs(a, i + 1, cur, ans);
        cur.pop_back();
    }
}

vector<vector<int>> subsets(const vector<int>& a) {
    vector<vector<int>> ans;
    vector<int> cur;
    dfs(a, 0, cur, ans);
    return ans;
}

void dfs(const vector<int>& a, vector<bool>& used, vector<int>& cur, vector<vector<int>>& ans) {
    if (cur.size() == a.size()) {
        ans.push_back(cur);
        return;
    }
    for (int i = 0; i < (int)a.size(); i++) {
        if (used[i]) continue;
        used[i] = true;
        cur.push_back(a[i]);
        dfs(a, used, cur, ans);
        cur.pop_back();
        used[i] = false;
    }
}

vector<vector<int>> permutations(const vector<int>& a) {
    vector<vector<int>> ans;
    vector<int> cur;
    vector<bool> used(a.size(), false);
    dfs(a, used, cur, ans);
    return ans;
}

void dfs(int n, int k, int start, vector<int>& cur, vector<vector<int>>& ans) {
    if ((int)cur.size() == k) {
        ans.push_back(cur);
        return;
    }
    for (int x = start; x <= n; x++) {
        cur.push_back(x);
        dfs(n, k, x + 1, cur, ans);
        cur.pop_back();
    }
}

vector<vector<int>> combinations(int n, int k) {
    vector<vector<int>> ans;
    vector<int> cur;
    dfs(n, k, 1, cur, ans);
    return ans;
}

void dfs(const vector<int>& a, int start, int remain, vector<int>& cur, vector<vector<int>>& ans) {
    if (remain == 0) {
        ans.push_back(cur);
        return;
    }
    for (int i = start; i < (int)a.size() && a[i] <= remain; i++) {
        if (i > start && a[i] == a[i - 1]) continue;
        cur.push_back(a[i]);
        dfs(a, i + 1, remain - a[i], cur, ans);
        cur.pop_back();
    }
}

vector<vector<int>> combinationSum(vector<int> a, int target) {
    sort(a.begin(), a.end());
    vector<vector<int>> ans;
    vector<int> cur;
    dfs(a, 0, target, cur, ans);
    return ans;
}

int maxNonAdjacent(const vector<int>& a) {
    int prev2 = 0, prev1 = 0;
    for (int x : a) {
        int cur = max(prev1, prev2 + x);
        prev2 = prev1;
        prev1 = cur;
    }
    return prev1;
}

int minPathSum(const vector<vector<int>>& grid) {
    int m = grid.size(), n = grid[0].size();
    vector<vector<int>> dp(m + 1, vector<int>(n + 1, INT_MAX));
    dp[0][1] = 0;
    for (int i = 1; i <= m; i++) {
        for (int j = 1; j <= n; j++) {
            dp[i][j] = grid[i - 1][j - 1] + min(dp[i - 1][j], dp[i][j - 1]);
        }
    }
    return dp[m][n];
}

int lengthOfLIS(const vector<int>& a) {
    vector<int> tails;
    for (int x : a) {
        auto it = lower_bound(tails.begin(), tails.end(), x);
        if (it == tails.end()) tails.push_back(x);
        else *it = x;
    }
    return tails.size();
}

int lcs(const string& s, const string& t) {
    int m = s.size(), n = t.size();
    vector<vector<int>> dp(m + 1, vector<int>(n + 1));
    for (int i = 1; i <= m; i++) {
        for (int j = 1; j <= n; j++) {
            if (s[i - 1] == t[j - 1]) dp[i][j] = dp[i - 1][j - 1] + 1;
            else dp[i][j] = max(dp[i - 1][j], dp[i][j - 1]);
        }
    }
    return dp[m][n];
}

int editDistance(const string& s, const string& t) {
    int m = s.size(), n = t.size();
    vector<vector<int>> dp(m + 1, vector<int>(n + 1));
    for (int i = 0; i <= m; i++) dp[i][0] = i;
    for (int j = 0; j <= n; j++) dp[0][j] = j;
    for (int i = 1; i <= m; i++) {
        for (int j = 1; j <= n; j++) {
            if (s[i - 1] == t[j - 1]) dp[i][j] = dp[i - 1][j - 1];
            else dp[i][j] = 1 + min({dp[i - 1][j], dp[i][j - 1], dp[i - 1][j - 1]});
        }
    }
    return dp[m][n];
}

int knapsack(const vector<int>& w, const vector<int>& v, int cap) {
    int n = w.size();
    vector<int> dp(cap + 1, 0);
    for (int i = 0; i < n; i++) {
        for (int c = cap; c >= w[i]; c--) {
            dp[c] = max(dp[c], dp[c - w[i]] + v[i]);
        }
    }
    return dp[cap];
}

int unboundedKnapsack(const vector<int>& w, const vector<int>& v, int cap) {
    int n = w.size();
    vector<int> dp(cap + 1, 0);
    for (int i = 0; i < n; i++) {
        for (int c = w[i]; c <= cap; c++) {
            dp[c] = max(dp[c], dp[c - w[i]] + v[i]);
        }
    }
    return dp[cap];
}

vector<vector<int>> mergeIntervals(vector<vector<int>> intervals) {
    sort(intervals.begin(), intervals.end());
    vector<vector<int>> ans;
    for (const auto& iv : intervals) {
        if (ans.empty() || ans.back()[1] < iv[0]) ans.push_back(iv);
        else ans.back()[1] = max(ans.back()[1], iv[1]);
    }
    return ans;
}

int minMergeCost(const vector<int>& a) {
    int n = a.size();
    vector<int> pre(n + 1, 0);
    for (int i = 0; i < n; i++) pre[i + 1] = pre[i] + a[i];
    vector<vector<int>> dp(n, vector<int>(n, 0));
    for (int len = 2; len <= n; len++) {
        for (int i = 0; i + len <= n; i++) {
            int j = i + len - 1;
            dp[i][j] = INT_MAX;
            for (int k = i; k < j; k++) {
                dp[i][j] = min(dp[i][j], dp[i][k] + dp[k + 1][j]);
            }
            dp[i][j] += pre[j + 1] - pre[i];
        }
    }
    return dp[0][n - 1];
}

int minAssignment(const vector<vector<int>>& cost) {
    int n = cost.size();
    vector<int> dp(1 << n, INT_MAX);
    dp[0] = 0;
    for (int mask = 0; mask < (1 << n); mask++) {
        int i = __builtin_popcount(mask);
        for (int j = 0; j < n; j++) {
            if (mask & (1 << j)) continue;
            int nxt = mask | (1 << j);
            dp[nxt] = min(dp[nxt], dp[mask] + cost[i][j]);
        }
    }
    return dp[(1 << n) - 1];
}

int dfs(int u, const vector<vector<int>>& adj, vector<int>& memo) {
    if (memo[u] != -1) return memo[u];
    int best = 0;
    for (int v : adj[u]) best = max(best, 1 + dfs(v, adj, memo));
    memo[u] = best;
    return best;
}

int longestPath(int n, const vector<vector<int>>& adj) {
    vector<int> memo(n, -1);
    int ans = 0;
    for (int u = 0; u < n; u++) ans = max(ans, dfs(u, adj, memo));
    return ans;
}

int partition(vector<int>& a, int lo, int hi) {
    int pivot = a[hi - 1];
    int i = lo;
    for (int j = lo; j < hi; j++) {
        if (a[j] < pivot) swap(a[i++], a[j]);
    }
    swap(a[i], a[hi - 1]);
    return i;
}

int quickselect(vector<int> a, int k) {
    int lo = 0, hi = a.size();
    while (lo < hi) {
        swap(a[lo + rand() % (hi - lo)], a[hi - 1]);
        int p = partition(a, lo, hi);
        if (p == k) return a[p];
        if (p < k) lo = p + 1;
        else hi = p;
    }
    return -1;
}

void mergeSort(vector<int>& a, int lo, int hi) {
    if (hi - lo <= 1) return;
    int mid = lo + (hi - lo) / 2;
    mergeSort(a, lo, mid);
    mergeSort(a, mid, hi);
    vector<int> tmp;
    int i = lo, j = mid;
    while (i < mid && j < hi) {
        if (a[i] <= a[j]) tmp.push_back(a[i++]);
        else tmp.push_back(a[j++]);
    }
    while (i < mid) tmp.push_back(a[i++]);
    while (j < hi) tmp.push_back(a[j++]);
    copy(tmp.begin(), tmp.end(), a.begin() + lo);
}

struct LRUCache {
    int cap;
    list<pair<int, int>> items;
    unordered_map<int, list<pair<int, int>>::iterator> pos;
    LRUCache(int capacity) : cap(capacity) {}
    int get(int key) {
        if (!pos.count(key)) return -1;
        items.splice(items.begin(), items, pos[key]);
        return items.front().second;
    }
    void put(int key, int value) {
        if (pos.count(key)) {
            get(key);
            items.front().second = value;
            return;
        }
        if ((int)items.size() == cap) {
            pos.erase(items.back().first);
            items.pop_back();
        }
        items.push_front({key, value});
        pos[key] = items.begin();
    }
};

long long power(long long base, long long exp, long long mod) {
    long long ans = 1;
    base %= mod;
    while (exp > 0) {
        if (exp & 1) ans = ans * base % mod;
        base = base * base % mod;
        exp >>= 1;
    }
    return ans;
}

int gcd(int a, int b) {
    return b == 0 ? a : gcd(b, a % b);
}

vector<int> sieve(int n) {
    vector<bool> isPrime(n + 1, true);
    vector<int> primes;
    for (int i = 2; i <= n; i++) {
        if (!isPrime[i]) continue;
        primes.push_back(i);
        for (long long j = 1LL * i * i; j <= n; j += i) isPrime[j] = false;
    }
    return primes;
}

struct SegTree {
    int n;
    vector<int> t;
    SegTree(const vector<int>& a) : n(a.size()), t(2 * n) {
        for (int i = 0; i < n; i++) t[n + i] = a[i];
        for (int i = n - 1; i > 0; i--) t[i] = t[2 * i] + t[2 * i + 1];
    }
    void update(int i, int val) {
        i += n;
        t[i] = val;
        for (i /= 2; i >= 1; i /= 2) t[i] = t[2 * i] + t[2 * i + 1];
    }
    int query(int l, int r) {
        int sum = 0;
        for (l += n, r += n; l < r; l /= 2, r /= 2) {
            if (l & 1) sum += t[l++];
            if (r & 1) sum += t[--r];
        }
        return sum;
    }
};

struct Fenwick {
    vector<int> t;
    Fenwick(int n) : t(n + 1, 0) {}
    void add(int i, int delta) {
        for (i++; i < (int)t.size(); i += i & -i) t[i] += delta;
    }
    int prefix(int i) {
        int sum = 0;
        for (; i > 0; i -= i & -i) sum += t[i];
        return sum;
    }
};

vector<int> prefixFunction(const string& s) {
    int n = s.size();
    vector<int> pi(n, 0);
    for (int i = 1; i < n; i++) {
        int k = pi[i - 1];
        while (k > 0 && s[i] != s[k]) k = pi[k - 1];
        if (s[i] == s[k]) k++;
        pi[i] = k;
    }
    return pi;
}

const long long BASE = 131, MOD = 1000000007;

struct StringHash {
    vector<long long> h, p;
    StringHash(const string& s) : h(s.size() + 1, 0), p(s.size() + 1, 1) {
        int n = s.size();
        for (int i = 0; i < n; i++) {
            h[i + 1] = (h[i] * BASE + s[i]) % MOD;
            p[i + 1] = p[i] * BASE % MOD;
        }
    }
    long long get(int l, int r) {
        return ((h[r] - h[l] * p[r - l]) % MOD + MOD) % MOD;
    }
};

vector<int> reservoirSample(const vector<int>& stream, int k) {
    vector<int> ans(stream.begin(), stream.begin() + k);
    int n = stream.size();
    for (int i = k; i < n; i++) {
        int j = rand() % (i + 1);
        if (j < k) ans[j] = stream[i];
    }
    return ans;
}
